We'll want to optimize these branches for performance later, as the normal case will be to push next, so perhaps:

```
if (!empty) ctx.push(resultIterator.next()) // Normal case, branch hit immediately
else if (terminated) ctx.finish()
else ctx.pull()
```

```
 final case class Recover[T](recovery: PartialFunction[Throwable, T]) extends PushPullStage[T, T] {
   private var recoverElement: T = _

   override def onPush(elem: T, ctx: Context[T]): Directive = ctx.push(elem)

   override def onPull(ctx: Context[T]): Directive = {
     if (ctx.isFinishing) ctx.push(recoverElement)
     else ctx.pull()
   }

   override def onUpstreamFailure(cause: scala.Throwable, ctx: Context[T]): TerminationDirective = {
     if (recovery.isDefinedAt(cause)) {
       recoverElement = recovery(cause)
       ctx.absorbTermination()
     } else ctx.fail(cause)
   }
 }
```

